const logicItem = $('Get SILVER Logic Document').first().json;
const marketItem = $('Build SILVER Input Pack').first().json;

let logicDocument = logicItem.content || '';

if (logicItem.encoding === 'base64') {
  logicDocument = Buffer.from(logicDocument, 'base64').toString('utf8');
}

return [
  {
    json: {
      logic_document: logicDocument,
      market_snapshot: marketItem
    }
  }
];

const item = $input.first().json;
const inputs = item.market_inputs || {};

function n(v) {
  const x = Number(v);
  return Number.isFinite(x) ? x : null;
}

function makeFactor(signal, evidence, reason) {
  return { signal, evidence, reason };
}

function safeJson(value) {
  try {
    return JSON.stringify(value);
  } catch (error) {
    return String(value || "");
  }
}

// Evidence strings must be readable; raw ratio math produces values like
// 9.999999999999964 which read as noise on the dashboard.
function fmt(value, decimals = 2) {
  const n = Number(value);
  if (!Number.isFinite(n)) return value;
  return Number(n.toFixed(decimals));
}

// SILVER weight hypotheses. Silver is a USD-priced industrial/precious hybrid,
// so the weighting deliberately differs from Gold: the industrial-demand and
// growth blocks (F8, F9) carry materially more weight than they do for Gold,
// and the risk block (F6) is signed the opposite way (see F6 below).
const TIMEFRAME_WEIGHTS = {
  "24h": { F1: 24, F2: 18, F3: 10, F4: 12, F5: 12, F6: 8, F7: 6, F8: 5, F9: 4, F10: 1 },
  "3d": { F1: 22, F2: 18, F3: 10, F4: 12, F5: 12, F6: 8, F7: 6, F8: 6, F9: 5, F10: 1 },
  "current_week": { F1: 20, F2: 17, F3: 10, F4: 12, F5: 12, F6: 8, F7: 6, F8: 7, F9: 7, F10: 1 },
  "next_week": { F1: 18, F2: 16, F3: 11, F4: 11, F5: 12, F6: 7, F7: 5, F8: 9, F9: 10, F10: 1 },
  "current_month": { F1: 16, F2: 15, F3: 11, F4: 10, F5: 12, F6: 6, F7: 4, F8: 11, F9: 14, F10: 1 }
};

function factorSignals(tf) {
  const use20d = tf === "next_week" || tf === "current_month";

  const realYieldDelta =
    use20d && n(inputs.us_10y_real_yield_d20_bps) !== null
      ? n(inputs.us_10y_real_yield_d20_bps)
      : n(inputs.us_10y_real_yield_d5_bps);

  const dxyDelta =
    use20d && n(inputs.dxy_d20) !== null
      ? n(inputs.dxy_d20)
      : tf === "24h" && n(inputs.dxy_d1) !== null
        ? n(inputs.dxy_d1)
        : n(inputs.dxy_d5);

  const silverDelta =
    use20d && n(inputs.silver_d20_pct) !== null
      ? n(inputs.silver_d20_pct)
      : tf === "24h" && n(inputs.silver_d1_pct) !== null
        ? n(inputs.silver_d1_pct)
        : n(inputs.silver_d5_pct);

  const ratioDelta =
    use20d && n(inputs.gold_silver_ratio_d20_pct) !== null
      ? n(inputs.gold_silver_ratio_d20_pct)
      : n(inputs.gold_silver_ratio_d5_pct);

  const vix = n(inputs.vix_level);
  const fed = String(inputs.fed_bias || "").toLowerCase();
  const growth = String(inputs.global_growth_regime || inputs.growth_regime || "").toLowerCase();
  const industrial = String(inputs.industrial_demand_regime || "").toLowerCase();
  const copper3m = n(inputs.copper_3m_pct);

  const signals = {};

  signals.F1 = (() => {
    if (realYieldDelta === null) return makeFactor("NEUTRAL", "Missing real yield delta", "Missing input");
    if (realYieldDelta <= -5) return makeFactor("BULLISH", `Real yield ${fmt(realYieldDelta, 1)}bps`, "Falling real yields reduce the opportunity cost of holding Silver");
    if (realYieldDelta >= 5) return makeFactor("BEARISH", `Real yield ${fmt(realYieldDelta, 1)}bps`, "Rising real yields raise the opportunity cost of holding Silver");
    return makeFactor("NEUTRAL", `Real yield ${fmt(realYieldDelta, 1)}bps`, "Real yield move below threshold");
  })();

  signals.F2 = (() => {
    if (dxyDelta === null) return makeFactor("NEUTRAL", "Missing DXY delta", "Missing input");
    const threshold = tf === "24h" ? 0.15 : 0.3;
    if (dxyDelta <= -threshold) return makeFactor("BULLISH", `DXY ${fmt(dxyDelta)}%`, "Dollar weakness is mechanically supportive for a USD-priced metal");
    if (dxyDelta >= threshold) return makeFactor("BEARISH", `DXY ${fmt(dxyDelta)}%`, "Dollar strength is mechanically restrictive for a USD-priced metal");
    return makeFactor("NEUTRAL", `DXY ${fmt(dxyDelta)}%`, "DXY move below threshold");
  })();

  signals.F3 = (() => {
    if (!fed || fed === "unknown") return makeFactor("NEUTRAL", "Fed bias unknown", "Missing input");
    if (fed.includes("dovish")) return makeFactor("BULLISH", `Fed bias ${fed}`, "Dovish Fed supports metals through lower real-yield expectations");
    if (fed.includes("hawkish")) return makeFactor("BEARISH", `Fed bias ${fed}`, "Hawkish Fed pressures metals through higher real-yield expectations");
    return makeFactor("NEUTRAL", `Fed bias ${fed}`, "No clear Fed impulse");
  })();

  signals.F4 = (() => {
    if (silverDelta === null) return makeFactor("NEUTRAL", "Missing Silver delta", "Missing input");
    const threshold = tf === "24h" ? 0.5 : 0.8;
    if (silverDelta >= threshold) return makeFactor("BULLISH", `Silver ${fmt(silverDelta)}%`, "Silver own-price trend confirms upside pressure");
    if (silverDelta <= -threshold) return makeFactor("BEARISH", `Silver ${fmt(silverDelta)}%`, "Silver own-price trend confirms downside pressure");
    return makeFactor("NEUTRAL", `Silver ${fmt(silverDelta)}%`, "Silver price move below threshold");
  })();

  signals.F5 = (() => {
    if (ratioDelta === null) return makeFactor("NEUTRAL", "Missing gold/silver ratio delta", "Missing input");
    const threshold = tf === "24h" ? 1.0 : 2.0;
    if (ratioDelta >= threshold) return makeFactor("BEARISH", `Gold/silver ratio ${fmt(ratioDelta, 1)}%`, "A rising ratio means Silver is underperforming Gold");
    if (ratioDelta <= -threshold) return makeFactor("BULLISH", `Gold/silver ratio ${fmt(ratioDelta, 1)}%`, "A falling ratio means Silver is outperforming Gold");
    return makeFactor("NEUTRAL", `Gold/silver ratio ${fmt(ratioDelta, 1)}%`, "Relative move below threshold");
  })();

  signals.F6 = (() => {
    if (vix === null) return makeFactor("NEUTRAL", "Missing VIX", "Missing input");
    // Deliberately signed opposite to Gold. Silver carries a large industrial
    // and liquidity-sensitive component, so risk-off liquidation is treated as
    // pressure rather than as a safe-haven bid.
    if (vix > 28) return makeFactor("BEARISH", `VIX ${vix}`, "Risk-off liquidation pressure typically hits Silver harder than Gold");
    if (vix < 16) return makeFactor("BULLISH", `VIX ${vix}`, "Risk-on conditions support Silver's industrial and liquidity-sensitive demand");
    return makeFactor("NEUTRAL", `VIX ${vix}`, "Neutral risk regime");
  })();

  signals.F7 = (() => {
    const ev = inputs.latest_us_event;
    const text = safeJson(ev).toLowerCase();
    if (!ev || text === "{}") return makeFactor("NEUTRAL", "No recent US event", "No confirmed US economic surprise");
    if (text.includes("negative") || text.includes("miss") || text.includes("bearish")) {
      return makeFactor("BULLISH", safeJson(ev), "Negative US surprise supports metals through lower yield and Fed repricing risk");
    }
    if (text.includes("positive") || text.includes("beat") || text.includes("bullish")) {
      return makeFactor("BEARISH", safeJson(ev), "Positive US surprise pressures metals through higher yield and Fed repricing risk");
    }
    return makeFactor("NEUTRAL", safeJson(ev), "No clear Silver signal from latest US event");
  })();

  signals.F8 = (() => {
    if (industrial.includes("expanding")) {
      return makeFactor("BULLISH", `Industrial demand ${industrial}`, "Expanding industrial demand supports Silver's fabrication demand");
    }
    if (industrial.includes("contracting")) {
      return makeFactor("BEARISH", `Industrial demand ${industrial}`, "Contracting industrial demand pressures Silver's fabrication demand");
    }
    if (copper3m !== null && Math.abs(copper3m) > 2) {
      return makeFactor("NEUTRAL", `Copper 3m ${copper3m}%`, "Metal complex and production series disagree, so industrial demand stays neutral");
    }
    return makeFactor("NEUTRAL", industrial || "neutral", "No clear industrial demand signal");
  })();

  signals.F9 = (() => {
    if (growth.includes("weakening") || growth.includes("contraction")) {
      return makeFactor("BEARISH", growth, "Weakening growth reduces cyclical Silver demand");
    }
    if (growth.includes("supportive") || growth.includes("expansion") || growth.includes("improving")) {
      return makeFactor("BULLISH", growth, "Improving growth supports cyclical Silver demand");
    }
    return makeFactor("NEUTRAL", growth || "neutral", "No clear growth or liquidity signal");
  })();

  signals.F10 = (() => {
    const supply = inputs.silver_supply_event;
    if (supply === null || supply === undefined || supply === "" || safeJson(supply) === "{}") {
      return makeFactor("NEUTRAL", "No verified supply/event feed", "No verified physical Silver supply or event source is wired");
    }
    const text = safeJson(supply).toLowerCase();
    if (text.includes("constrain") || text.includes("deficit") || text.includes("disrupt")) {
      return makeFactor("BULLISH", text, "Constrained supply supports Silver");
    }
    if (text.includes("surplus") || text.includes("oversupply")) {
      return makeFactor("BEARISH", text, "Supply surplus pressures Silver");
    }
    return makeFactor("NEUTRAL", text, "Supply/event context is not directional");
  })();

  return signals;
}

function scoreTimeframe(tf) {
  const weights = TIMEFRAME_WEIGHTS[tf];
  const signals = factorSignals(tf);

  let bullish = 0;
  let bearish = 0;
  let neutral = 0;
  let bullishCount = 0;
  let bearishCount = 0;
  let neutralCount = 0;

  const factorBreakdown = {};

  for (const [id, sig] of Object.entries(signals)) {
    const weight = weights[id] || 0;
    factorBreakdown[id] = { ...sig, weight };

    if (sig.signal === "BULLISH") {
      bullish += weight;
      bullishCount++;
    } else if (sig.signal === "BEARISH") {
      bearish += weight;
      bearishCount++;
    } else {
      neutral += weight;
      neutralCount++;
    }
  }

  const active = bullish + bearish;
  const participation = active;

  const bullishArgument = active > 0 ? Math.round((bullish / active) * 100) : 0;
  const bearishArgument = active > 0 ? Math.round((bearish / active) * 100) : 0;
  const neutralPct = Math.round(neutral);
  const netEdge = bullishArgument - bearishArgument;

  const baseDirection =
    bullish > bearish ? "BULLISH" : bearish > bullish ? "BEARISH" : "NO_CLEAR_BIAS";

  const absEdge = Math.abs(netEdge);
  const weightMargin = Math.abs(bullish - bearish);

  const direction =
    baseDirection === "NO_CLEAR_BIAS"
      ? "NO_CLEAR_BIAS"
      : active < 50 || weightMargin < 15 || absEdge < 20
        ? `${baseDirection}_LEAN`
        : baseDirection;

  const winningArgument =
    baseDirection === "BULLISH" ? bullishArgument : baseDirection === "BEARISH" ? bearishArgument : 0;

  const participationCap = Math.min(participation, 80);

  const conviction =
    baseDirection === "NO_CLEAR_BIAS"
      ? 0
      : Math.round(winningArgument * (participationCap / 100));

  const strength =
    absEdge >= 40 && participation >= 70 ? "VERY_STRONG" :
    absEdge >= 25 && participation >= 50 ? "STRONG" :
    absEdge >= 15 ? "MODERATE" :
    "WEAK";

  const reason =
    `${tf} deterministic Silver score: bull case ${bullishArgument}%, bear case ${bearishArgument}%, ` +
    `directional participation ${participation}%, neutral/inactive ${neutralPct}%, net edge ${netEdge > 0 ? "+" : ""}${netEdge}. ` +
    `Real yields and the dollar remain the highest-priority Silver drivers, with industrial demand weighted above the Gold weighting.`;

  return {
    direction,
    conviction,
    reason,
    factor_breakdown: factorBreakdown,
    score_bullish: bullishCount,
    score_bearish: bearishCount,
    score_neutral: neutralCount,
    weighted_score: {
      bullish_weight: bullish,
      bearish_weight: bearish,
      neutral_weight: neutral,
      active_weight: active,
      weight_margin: weightMargin
    },
    conviction_model: {
      bull_case: bullishArgument,
      bear_case: bearishArgument,
      winning_side: baseDirection,
      directional_participation: participation,
      net_edge: netEdge,
      final_conviction: conviction,
      verdict_strength: strength,
      final_conviction_logic: reason,
      bullish_argument_pct: bullishArgument,
      bearish_argument_pct: bearishArgument,
      neutral_pct: neutralPct,
      active_participation_pct: participation,
      net_edge_pct: netEdge,
      weighted_edge: Math.abs(netEdge) / 100,
      raw_conviction: conviction,
      base_conviction: conviction,
      participation,
      participation_cap: participationCap,
      conflict_penalty: 0,
      missing_input_penalty: 0,
      agreement_boost: 0
    }
  };
}

const r24h = scoreTimeframe("24h");
const r3d = scoreTimeframe("3d");
const rWeek = scoreTimeframe("current_week");
const rNextWeek = scoreTimeframe("next_week");
const rMonth = scoreTimeframe("current_month");

const output = {
  ...(item.full_output || {}),

  asset: "SILVER",
  agent_name: "SILVER",
  logic_document: "agent_silver_direction.md",
  logic_document_version: "1.0_weighted_engine",

  direction_24h: r24h.direction,
  conviction_24h: r24h.conviction,
  reason_24h: r24h.reason,

  direction_3_day: r3d.direction,
  conviction_3_day: r3d.conviction,
  reason_3_day: r3d.reason,

  direction_current_week: rWeek.direction,
  conviction_current_week: rWeek.conviction,
  reason_current_week: rWeek.reason,

  direction_next_week: rNextWeek.direction,
  conviction_next_week: rNextWeek.conviction,
  reason_next_week: rNextWeek.reason,

  direction_current_month: rMonth.direction,
  conviction_current_month: rMonth.conviction,
  reason_current_month: rMonth.reason,

  weighted_score: r24h.weighted_score,
  conviction_model: r24h.conviction_model,
  factor_breakdown: r24h.factor_breakdown,

  timeframe_models: {
    "24h": r24h,
    "3d": r3d,
    "current_week": rWeek,
    "next_week": rNextWeek,
    "current_month": rMonth
  },

  score_bullish: r24h.score_bullish,
  score_bearish: r24h.score_bearish,
  score_neutral: r24h.score_neutral,

  reasoning_summary:
    `SILVER weighted verdicts calculated deterministically by timeframe. ` +
    `24h ${r24h.direction} ${r24h.conviction}%, ` +
    `3d ${r3d.direction} ${r3d.conviction}%, ` +
    `current week ${rWeek.direction} ${rWeek.conviction}%, ` +
    `next week ${rNextWeek.direction} ${rNextWeek.conviction}%, ` +
    `current month ${rMonth.direction} ${rMonth.conviction}%.`
};

const { market_inputs, ...safeItem } = item;

delete safeItem.non_neutral_count;
delete safeItem.missing_inputs;
delete safeItem.timeframe_models;

return [{
  json: {
    ...safeItem,

    agent_name: "SILVER",
    logic_document: "agent_silver_direction.md",
    logic_document_version: "1.0_weighted_engine",

    call_24h_direction: output.direction_24h,
    call_24h_conviction: output.conviction_24h,
    call_24h_reason: output.reason_24h,

    call_3d_direction: output.direction_3_day,
    call_3d_conviction: output.conviction_3_day,
    call_3d_reason: output.reason_3_day,

    call_current_week_direction: output.direction_current_week,
    call_current_week_conviction: output.conviction_current_week,
    call_current_week_reason: output.reason_current_week,

    call_next_week_direction: output.direction_next_week,
    call_next_week_conviction: output.conviction_next_week,
    call_next_week_reason: output.reason_next_week,

    call_current_month_direction: output.direction_current_month,
    call_current_month_conviction: output.conviction_current_month,
    call_current_month_reason: output.reason_current_month,

    direction_24h: output.direction_24h,
    conviction_24h: output.conviction_24h,

    direction_3_day: output.direction_3_day,
    conviction_3_day: output.conviction_3_day,

    direction_current_week: output.direction_current_week,
    conviction_current_week: output.conviction_current_week,

    direction_next_week: output.direction_next_week,
    conviction_next_week: output.conviction_next_week,

    direction_current_month: output.direction_current_month,
    conviction_current_month: output.conviction_current_month,

    factor_breakdown: output.factor_breakdown,
    weighted_score: output.weighted_score,
    conviction_model: output.conviction_model,

    full_output: output,
    raw_agent_output: output,

    reasoning_summary: output.reasoning_summary,
    score_bullish: output.score_bullish,
    score_bearish: output.score_bearish,
    score_neutral: output.score_neutral
  }
}];
